import React from 'react';
import { Link, useNavigate } from 'react-router-dom';

const Navbar = () => {
  const navigate = useNavigate();

  return (
    <nav style={{ 
      backgroundColor: '#fff', 
      padding: '15px 40px', 
      display: 'flex', 
      justifyContent: 'space-between', 
      alignItems: 'center',
      boxShadow: '0 2px 10px rgba(0,0,0,0.05)',
      position: 'sticky',
      top: 0,
      zIndex: 100
    }}>
      {/* LOGO */}
      <Link to="/" style={{ textDecoration: 'none', color: '#4a3b52', fontSize: '1.5rem', fontWeight: 'bold' }}>
        CampusNest ✨
      </Link>

      {/* NAVIGATION LINKS */}
      <div style={{ display: 'flex', gap: '20px', alignItems: 'center' }}>
        <Link to="/" style={{ textDecoration: 'none', color: '#786d84', fontWeight: '500' }}>
          Home (Student)
        </Link>
        <Link to="/owner" style={{ textDecoration: 'none', color: '#786d84', fontWeight: '500' }}>
          Owner Dashboard
        </Link>
        
        {/* LOGIN BUTTON */}
        <button 
          onClick={() => navigate('/login')}
          style={{ 
            padding: '8px 20px', 
            backgroundColor: '#e6d9ef', 
            color: '#4a3b52', 
            border: 'none', 
            borderRadius: '20px', 
            fontWeight: 'bold',
            cursor: 'pointer' 
          }}>
          Login / Sign Up
        </button>
      </div>
    </nav>
  );
};

export default Navbar;
